Given the head of singly linked list, find middle node of the linked list.If the number of nodes is odd, return the middle node.If the number of nodes is even, there are two middle nodes, so return the second middle node.Example:Input:  Output: 3 Explanation: There are 5 nodes in the linked list and there is one middle node whose value is 3.Input: Output: 40Explanation: There are 6 nodes in the linked list, so we have two middle nodes: 30 and 40, but we will return the second middle node which is 40.Try It YourselfTable of Content[Naive Approach] Two Passes - O(n) Time and O(1) Space[Expected Approach] Hare and Tortoise Algorithm - O(n) Time and O(1) Space[Naive Approach] Two Passes - O(n) Time and O(1) SpaceThe idea is to traverse the entire linked list once to count the total number of nodes. After determining the total count, traverse the list again and stop at the (count/2)th node to return its value. This method requires two passes through the linked list to find the middle element.
            C++

    #include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int x) {
        this->data = x;
        this->next = nullptr;
    }
};

int getLength(Node* head) {

    int length = 0;

    // Count nodes in linked list
    while (head) {
        length++;
        head = head->next;
    }

    return length;
}

int getMiddle(Node* head) {

    // finding length of the linked list
    int length = getLength(head);

    // traverse till we reached half of length
    int midIndex = length / 2;
    while (midIndex--) {
        head = head->next;
    }

    return head->data;
}

int main() {

    Node* head = new Node(10);
    head->next = new Node(20);
    head->next->next = new Node(30);
    head->next->next->next = new Node(40);
    head->next->next->next->next = new Node(50);
    head->next->next->next->next->next = new Node(60);

    cout << getMiddle(head);

    return 0;
}


